import{_ as d,o as r,c as o,a2 as a}from"./chunks/framework.Bqa2y7hU.js";const b=JSON.parse('{"title":"名词表","description":"Xiaoyi_QQ_V4 文档里反复出现的术语：框架、适配器、机器人、插件、能力码、事件等。","frontmatter":{"title":"名词表","description":"Xiaoyi_QQ_V4 文档里反复出现的术语：框架、适配器、机器人、插件、能力码、事件等。"},"headers":[],"relativePath":"guide/glossary.md","filePath":"guide/glossary.md","lastUpdated":1790419519000}'),e={name:"guide/glossary.md"};function n(s,t,g,h,i,l){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="名词表" tabindex="-1">名词表 <a class="header-anchor" href="#名词表" aria-label="Permalink to &quot;名词表&quot;">​</a></h1><p>文档里出现的术语，按出现频率从高到低排列。看文档时遇到不认识的词，回这页查。</p><h2 id="框架与部署" tabindex="-1">框架与部署 <a class="header-anchor" href="#框架与部署" aria-label="Permalink to &quot;框架与部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td><strong>框架</strong></td><td>Xiaoyi_QQ_V4 本体，即那个可执行文件。所有机器人、插件都运行在它里面</td></tr><tr><td><strong>控制台</strong></td><td>框架自带的网页管理界面，默认在 <code>8080</code> 端口</td></tr><tr><td><strong>安装向导</strong></td><td>首次启动时自动进入的初始化页面，用来填数据库信息并创建管理员</td></tr><tr><td><strong>管理面 / 数据面</strong></td><td>管理面是控制台与接口（<code>8080</code>）；数据面是机器人连接的接入端口（<code>8081</code>）</td></tr><tr><td><strong>授权文件</strong></td><td>服务商提供的文件，放在程序同目录，用于启动校验</td></tr></tbody></table><h2 id="接入相关" tabindex="-1">接入相关 <a class="header-anchor" href="#接入相关" aria-label="Permalink to &quot;接入相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td><strong>适配器</strong></td><td>连接某一类平台的组件。目前有 QQ 官方与 OneBot 11 两种</td></tr><tr><td><strong>QQ 官方机器人</strong></td><td>在 QQ 开放平台创建的机器人，通过官方接口收发消息</td></tr><tr><td><strong>OneBot 11</strong></td><td>一套被广泛实现的机器人协议，通常由 NapCat、Lagrange、go-cqhttp 等实现端提供</td></tr><tr><td><strong>实现端</strong></td><td>在 OneBot 场景里，真正登录 QQ 并与框架对接的那个程序</td></tr><tr><td><strong>反向 WebSocket</strong></td><td>OneBot 实现端主动连到框架的模式（区别于框架去连实现端）</td></tr><tr><td><strong>Webhook</strong></td><td>平台主动把事件推给你的服务器，需要一个公网可访问的回调地址</td></tr><tr><td><strong>回调地址</strong></td><td>你提供给平台的 URL，格式形如 <code>{协议}://{域名}/api/webhooks/adapters/{适配器}/{机器人UUID}</code></td></tr><tr><td><strong>UUID</strong></td><td>每台机器人在框架内的唯一标识，回调地址、开放 API 里都会用到</td></tr><tr><td><strong>全量消息授权</strong></td><td>QQ 官方平台的一项设置，授权后机器人才能收到群里<strong>没有被 @</strong> 的消息</td></tr></tbody></table><h2 id="插件相关" tabindex="-1">插件相关 <a class="header-anchor" href="#插件相关" aria-label="Permalink to &quot;插件相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td><strong>插件</strong></td><td>独立的 <code>.so</code> 文件，装在机器人上运行，为机器人增加功能</td></tr><tr><td><strong>插件市场</strong></td><td>控制台里浏览、安装插件的页面</td></tr><tr><td><strong>绑定 / 安装到机器人</strong></td><td>把插件挂到某台机器人上，只对该机器人生效</td></tr><tr><td><strong>插件面板</strong></td><td>插件自带的网页配置界面，在机器人详情页里打开</td></tr><tr><td><strong>ABI</strong></td><td>插件与框架之间的二进制接口约定，有版本号；版本不匹配的插件会被拒绝加载</td></tr><tr><td><strong>SDK</strong></td><td>一个头文件，写插件时 <code>#include</code> 它就能用框架提供的能力</td></tr><tr><td><strong>元数据</strong></td><td>插件里声明自己名字、版本、分类、图标等信息的那部分</td></tr><tr><td><strong>事件</strong></td><td>框架交给插件的「发生了什么」，例如群消息、成员入群、入群申请、按钮点击</td></tr><tr><td><strong>拦截器</strong></td><td>插件在消息处理链路中插入的钩子，可以改写或阻断消息</td></tr><tr><td><strong>事件订阅</strong></td><td>插件声明自己只关心哪几类事件，其余事件不会被推给它</td></tr><tr><td><strong>云编译</strong></td><td>在线上把插件源码编译成插件包的服务，不用本地配 C++ 环境</td></tr></tbody></table><h2 id="能力调用" tabindex="-1">能力调用 <a class="header-anchor" href="#能力调用" aria-label="Permalink to &quot;能力调用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td><strong>平台能力</strong></td><td>平台提供的一组操作，例如禁言、踢人、撤回、审批入群</td></tr><tr><td><strong>能力码</strong></td><td>平台能力的统一编号，形如 <code>xubp.group.member.mute</code>。插件用它调用能力，不用关心背后是哪个平台</td></tr><tr><td><strong>能力探测</strong></td><td>调用前先问框架「这台机器人支持这个能力吗」，不支持时降级处理</td></tr><tr><td><strong>降级</strong></td><td>平台不支持某项能力时改用别的做法，例如按钮不可用时改发文字指令</td></tr></tbody></table><h2 id="账号与商业化" tabindex="-1">账号与商业化 <a class="header-anchor" href="#账号与商业化" aria-label="Permalink to &quot;账号与商业化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td><strong>用户</strong></td><td>控制台的使用者，可以拥有多台机器人</td></tr><tr><td><strong>管理员</strong></td><td>能进入平台管理后台的角色，管理用户、套餐、插件上架、平台配置</td></tr><tr><td><strong>套餐</strong></td><td>订阅方案，决定这个账号能拥有多少台机器人、安装多少个插件</td></tr><tr><td><strong>机器人位 / 插件位</strong></td><td>套餐里的配额单位：机器人位限制能建几台机器人，插件位限制能装多少插件；超配额时新建/安装都会被拒绝</td></tr><tr><td><strong>卡密</strong></td><td>一串兑换码，用户自助兑换成套餐或余额</td></tr><tr><td><strong>开放 API</strong></td><td>用 API Key 调用的接口，可以在程序外部查询状态或让机器人发消息</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/guide/what-is">为什么是 Xiaoyi_QQ_V4</a>：产品定位与组成</li><li><a href="/RuaBot.Doc/guide/features">核心特性</a>：能力逐项展开</li><li><a href="/RuaBot.Doc/faq">常见问题</a>：遇到问题先看这里</li></ul>',14)])])}const u=d(e,[["render",n]]);export{b as __pageData,u as default};
